package com.shikshasetu.ai;
import weka.classifiers.Classifier;import weka.core.Instances;import java.io.Serializable;import java.time.Instant;
public class ModelBundle implements Serializable {private static final long serialVersionUID=1L;private final Classifier classifier;private final Instances header;private final String modelVersion;private final Instant trainedAt;private final TrainingMetrics metrics;public ModelBundle(Classifier c,Instances h,String v,Instant t,TrainingMetrics m){classifier=c;header=h;modelVersion=v;trainedAt=t;metrics=m;}public Classifier getClassifier(){return classifier;}public Instances getHeader(){return header;}public String getModelVersion(){return modelVersion;}public Instant getTrainedAt(){return trainedAt;}public TrainingMetrics getMetrics(){return metrics;}}
